(()=>{const images=window.ATLAS_ILLUSTRATION_DATA?.images;if(!images)return;for(const [id,link] of Object.entries({"lisa-8d5484b0a7a3be":{"item":152,"objective":"152-12","pathway":"di50-152-priorites","decision":true,"note":"Les deux branches urgence/stabilité et la hiérarchie hémocultures–ETT–ETO sont conservées. Le délai historique de 24 h chez un patient stable est décrit, sans imposer un retard de prélèvement ou de traitement. Sepsis et défaillance imposent une prise en charge immédiate."},"lisa-d89e62f27da6bf":{"item":152,"objective":"152-10","pathway":"di50-152-echographie","decision":true,"note":"Les quatre situations après ETT et la bifurcation selon la suspicion sont conservées. Une ETT négative n’est pas une exclusion définitive ; le contrôle d’imagerie en cas de forte suspicion persistante est un complément actualisé."},"lisa-900f15b341b459":{"item":156,"objective":"156-7","pathway":"di50-156-ponction","decision":true,"note":"Les deux profils et les étiologies de la figure sont conservés. Correction de l’unité : cellules/mm³ (équivalent à cellules/µL), et non cellules/mL. Protéines et cellularité sont des repères d’orientation, sans seuil permettant d’exclure une infection. Les branches de sécurité vers l’urgence septique explicitent les réserves de l’image."},"lisa-01ff2e2984436c":{"item":158,"objective":"158-2","pathway":"di50-158-sepsis","decision":true,"note":"Arbre adulte : les définitions et scores pédiatriques sont différents et sont traités dans les objectifs associés. La figure indique SOFA ≥ 2 ; la transcription précise augmentation ≥ 2 par rapport à l’état basal. Le qSOFA ne suffit pas comme outil unique de dépistage ou d’exclusion."},"lisa-9eaf345b4b304e":{"item":169,"objective":"169-12","pathway":"di50-169-depistage","decision":true,"note":"Branches de confirmation, second prélèvement et recherche d’ARN conservées. Ajouts explicités : PrEP/TPE modifiant le calendrier ; ARN VIH-1 négatif n’excluant pas VIH-2 ; confirmation adaptée aux techniques du laboratoire."},"lisa-a1a328aa1fc966":{"item":170,"objective":"170-6","pathway":"di50-170-diagnostic","decision":true,"note":"Les alternatives de technique, l’identification et la parasitémie, ainsi que le contrôle à 12–24 h sont conservés. Le frottis et la technique sensible sont complémentaires ; un TDR négatif isolé n’élimine pas le paludisme."},"lisa-5f687d00f722d5":{"item":170,"objective":"170-8","pathway":"di50-170-traitement","decision":true,"note":"Les trois décisions gravité/vomissements/hospitalisation sont conservées. La quinine IV figurant dans l’image est signalée comme schéma de la figure ; le traitement parentéral actuel doit être choisi selon protocole expert. L’artésunate IV est la référence du paludisme grave."},"lisa-5ea573ab66d785":{"item":272,"objective":"272-15","pathway":"di50-272-hp","decision":true,"note":"Figure HAS mai 2017 conservée avec ses deux stratégies et les échecs de traitement. Les délais du contrôle et les doses du traitement guidé sont actualisés dans le cours. Les prescriptions doivent tenir compte des résistances, allergies et précautions ; la figure exclut grossesse et allaitement."},"lisa-cc978a67db02eb":{"item":274,"objective":"274-1","pathway":"di50-274-enfant","decision":true,"note":"Toutes les branches d’âge, d’évolution, d’abdomen chirurgical et de syndrome infectieux sont conservées, avec les diagnostics de chaque case. Compléments de sécurité : bilieux néonatal urgent, infection parfois sans fièvre, recherche de gravité avant classement. Le terme « psychogène » de la figure n’est pas un diagnostic automatique."},"lisa-4f91577ae0f4dc-p1":{"item":278,"objective":"278-3","pathway":"di50-278-neonatal","decision":true,"note":"Les deux fractions et les causes de la figure sont conservées. Les branches de gravité et de surveillance sont des compléments : le niveau de bilirubine s’interprète sur des courbes selon âge en heures, terme et facteurs de risque."},"lisa-14fa152c43bdd6":{"item":280,"objective":"280-4","pathway":"di50-280-ascite","decision":true,"note":"Les quatre profils protéines/GASA, leurs causes et examens sont conservés. Précision des bornes (≥ 11 et ≥ 25) et de la formule du GASA. Il s’agit d’orientations, pas de diagnostics certains. Le dépistage de l’infection est simultané."},"lisa-8c89d95a8af533":{"item":304,"objective":"304-4","pathway":"di50-304-tumeur","decision":true,"note":"La séparation foie avec/sans hépatopathie, l’imagerie multiphasique et les diagnostics de la figure sont conservés. Les cases finales sont développées avec les précautions de biopsie et les renvois au cours. Cette image et son autre version disposent chacune d’un accès interactif."},"lisa-1d31531c187227":{"item":304,"objective":"304-4","pathway":"di50-304-tumeur-variante","decision":true,"note":"La séparation foie avec/sans hépatopathie, l’imagerie multiphasique et les diagnostics de la figure sont conservés. Les cases finales sont développées avec les précautions de biopsie et les renvois au cours. Cette image et son autre version disposent chacune d’un accès interactif."},"lisa-3da7f7ce8a54a2":{"item":304,"objective":"304-6","pathway":"di50-304-metastase","decision":true,"note":"Les branches cancer connu/recherche du primitif/biopsie sont conservées. Le repère de 2–3 ans est contextualisé : il ne dispense pas automatiquement d’une preuve et n’exclut pas une récidive tardive."}}))if(images[id]){images[id].interactivePathway=link;images[id].algorithm=link.decision;}})();
